import {RADIO_STATIONS} from './audio-settings.mjs';
// Original 8-bar mini compositions, generated locally. No streamed songs.
export function createRadio(audio){const {ctx,master}=audio,gain=ctx.createGain();gain.gain.value=0;gain.connect(master);let station='',next=0,step=0;const active=new Set();
  const noise=ctx.createBuffer(1,ctx.sampleRate*.18,ctx.sampleRate);let seed=41;const d=noise.getChannelData(0);for(let i=0;i<d.length;i++){seed=(seed*1664525+1013904223)>>>0;d[i]=(seed/4294967296*2-1)*Math.exp(-i/d.length*8);}
  function tone(note,at,duration,amp,type='triangle',slide=0){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;const f=440*2**((note-69)/12);o.frequency.setValueAtTime(f*(1+slide),at);o.frequency.exponentialRampToValueAtTime(f,at+.07);g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(amp,at+.008);g.gain.exponentialRampToValueAtTime(.0001,at+duration);o.connect(g);g.connect(gain);o.start(at);o.stop(at+duration+.01);active.add(o);o.onended=()=>{active.delete(o);o.disconnect();g.disconnect();};}
  function hat(at,amp){const s=ctx.createBufferSource(),g=ctx.createGain(),f=ctx.createBiquadFilter();s.buffer=noise;f.type='highpass';f.frequency.value=4200;g.gain.value=amp;s.connect(f);f.connect(g);g.connect(gain);s.start(at);active.add(s);s.onended=()=>{active.delete(s);s.disconnect();g.disconnect();f.disconnect();};}
  function stopNotes(){for(const o of active)try{o.stop();}catch{}active.clear();}
  return {update({enabled,volume,stationId}){const t=ctx.currentTime,s=RADIO_STATIONS.find(s=>s.id===stationId)||RADIO_STATIONS[0];if(station!==s.id){station=s.id;step=0;next=t+.03;stopNotes();}gain.gain.setTargetAtTime(enabled?volume*(audio.voiceUntil>t?.37:1)*.68:0,t,.08);if(!enabled||volume<=0){next=t+.04;return;}if(next<t)next=t+.03;const eighth=60/s.bpm/2;while(next<t+.13){const beat=step%16,bar=Math.floor(step/16)%8,root=s.root+[0,0,5,0,7,5,0,7][bar];if(beat%4===0){tone(31,next,.17,.48,'sine',2);tone(root,next,eighth*1.7,.19,'triangle');}if(beat%4===2){hat(next,.22);tone(58,next,.055,.08,'triangle');}hat(next,beat%2?.08:.035);if(beat%2===1)for(const n of [0,s.id==='garage'?3:4,7])tone(root+12+n,next,eighth*.7,.043,s.wave);const m=s.melody[beat];if(m)tone(root+m,next,eighth*(beat%4===3?1.5:.8),s.id==='space'?.037:.12,s.wave,s.id==='garage'?.025:0);if(beat===15&&bar%2)tone(root+31,next+.06,.18,.09,'sine',.2);next+=eighth;step++;}},stop(){stopNotes();gain.gain.value=0;}};
}
